data = {}

def put(address, description, algorithm, inputs='', outputs='', corrupt='', effects=''):
    data[f'{address:04X}'] = dict(description=description, algorithm=algorithm,
        inputs=inputs, outputs=outputs, corrupt=corrupt, effects=effects,
        evidence='статический разбор декодированных машинных команд, без проверки в игре')

